// DSV4 Indexer CUDA kernel: RoPE (tail 64) + 128-pt Hadamard + FP8 E4M3 quantization
// Matches SGLang lane-major ordering for bit-exact parity.

#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cuda_fp8.h>
#include <cuda_runtime.h>
#include <cstdint>

// Constants
static constexpr int kWarpThreads = 32;
static constexpr int kHeadDim = 128;
static constexpr int kRopeDim = 64;
static constexpr int kVecSize = 4;  // Each thread handles 4 elements
static constexpr float kFP8E4M3Max = 448.0f;
static constexpr int kBlockSize = 128;  // 4 warps per block
static constexpr int kNumWarps = kBlockSize / kWarpThreads;

// Helper: convert bf16 to float
__device__ __forceinline__ float bf16_to_float(__nv_bfloat16 x) {
    return __bfloat162float(x);
}

// Helper: convert fp16 to float
__device__ __forceinline__ float fp16_to_float(__half x) {
    return __half2float(x);
}

// Helper: clamp value to FP8 range
__device__ __forceinline__ float fp8_e4m3_clip(float val) {
    return fmaxf(fminf(val, kFP8E4M3Max), -kFP8E4M3Max);
}

// Helper: pack two fp32 values into fp8x2
__device__ __forceinline__ __nv_fp8x2_e4m3 pack_fp8(float x, float y) {
    return __nv_fp8x2_e4m3(float2{fp8_e4m3_clip(x), fp8_e4m3_clip(y)});
}

// Warp-level max reduction
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = kWarpThreads / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_xor_sync(0xFFFFFFFF, val, offset));
    }
    return val;
}

// Aligned vector load/store helpers
template<typename T, int N>
struct alignas(sizeof(T) * N) AlignedVec {
    T data[N];
    __device__ __forceinline__ T& operator[](int i) { return data[i]; }
    __device__ __forceinline__ const T& operator[](int i) const { return data[i]; }

    __device__ __forceinline__ void load(const T* ptr, int idx) {
        *this = reinterpret_cast<const AlignedVec*>(ptr)[idx];
    }

    __device__ __forceinline__ void store(T* ptr, int idx) const {
        reinterpret_cast<AlignedVec*>(ptr)[idx] = *this;
    }
};

// Main kernel template
template<typename DType>
__global__ __launch_bounds__(kBlockSize, 16)
void fused_indexer_kernel(
    const DType* __restrict__ q_input,      // [B, H, 128]
    __nv_fp8_e4m3* __restrict__ q_fp8,      // [B, H, 128]
    const DType* __restrict__ weight,       // [B, H]
    float* __restrict__ weights_out,        // [B, H, 1]
    float weight_scale,
    const float* __restrict__ freqs_cis,    // [max_pos, 64] real/imag interleaved
    const int32_t* __restrict__ positions,  // [B]
    uint32_t batch_size,
    uint32_t num_heads
) {
    const uint32_t warp_id = threadIdx.x / kWarpThreads;
    const uint32_t lane_id = threadIdx.x % kWarpThreads;
    const uint32_t work_id = blockIdx.x * kNumWarps + warp_id;

    const uint32_t total_works = batch_size * num_heads;
    if (work_id >= total_works) return;

    const uint32_t batch_id = work_id / num_heads;
    const DType* input_ptr = q_input + work_id * kHeadDim;
    const int32_t position = positions[batch_id];
    const float* freq_ptr = freqs_cis + position * kRopeDim;

    // Last 16 lanes (lane_id >= 16) own the RoPE tail (64 elements / 4 per lane = 16 lanes)
    const bool is_rope_lane = lane_id >= (kWarpThreads - kRopeDim / kVecSize);

    // Load weight for this (batch, head)
    float weight_val;
    if constexpr (std::is_same_v<DType, __nv_bfloat16>) {
        weight_val = bf16_to_float(weight[work_id]);
    } else {
        weight_val = fp16_to_float(weight[work_id]);
    }

    // Part 1: Load data (each lane owns 4 elements)
    float data[kVecSize];
    float freq[kVecSize];

    AlignedVec<DType, kVecSize> input_vec;
    input_vec.load(input_ptr, lane_id);

    if (is_rope_lane) {
        AlignedVec<float, kVecSize> freq_vec;
        freq_vec.load(freq_ptr, lane_id - (kWarpThreads - kRopeDim / kVecSize));
        #pragma unroll
        for (int i = 0; i < kVecSize; ++i) {
            freq[i] = freq_vec[i];
        }
    }

    #pragma unroll
    for (int i = 0; i < kVecSize; ++i) {
        if constexpr (std::is_same_v<DType, __nv_bfloat16>) {
            data[i] = bf16_to_float(input_vec[i]);
        } else {
            data[i] = fp16_to_float(input_vec[i]);
        }
    }

    // Part 2: RoPE on tail lanes only (4 elems / lane = 2 (real, imag) pairs)
    if (is_rope_lane) {
        // First complex pair
        const float x_real = data[0];
        const float x_imag = data[1];
        const float fxr = freq[0];
        const float fxi = freq[1];

        // Second complex pair  
        const float y_real = data[2];
        const float y_imag = data[3];
        const float fyr = freq[2];
        const float fyi = freq[3];

        // Apply rotation: (x_real + i*x_imag) * (cos + i*sin)
        data[0] = x_real * fxr - x_imag * fxi;
        data[1] = x_real * fxi + x_imag * fxr;
        data[2] = y_real * fyr - y_imag * fyi;
        data[3] = y_real * fyi + y_imag * fyr;
    }

    // Part 3: 128-point Hadamard transform
    // Stage 1: Local 4-point Hadamard (2 butterflies)
    {
        const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
        data[0] = a0 + a1;
        data[1] = a0 - a1;
        data[2] = a2 + a3;
        data[3] = a2 - a3;
    }
    {
        const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
        data[0] = a0 + a2;
        data[1] = a1 + a3;
        data[2] = a0 - a2;
        data[3] = a1 - a3;
    }

    // Stage 2: Cross-lane shuffle butterflies (32 lanes = 5 stages)
    #pragma unroll
    for (uint32_t mask = 1; mask < kWarpThreads; mask <<= 1) {
        #pragma unroll
        for (int i = 0; i < kVecSize; ++i) {
            const float other = __shfl_xor_sync(0xFFFFFFFF, data[i], mask, kWarpThreads);
            data[i] = (lane_id & mask) ? (other - data[i]) : (data[i] + other);
        }
    }

    // Apply Hadamard normalization: 1/sqrt(128)
    const float kHadamardScale = rsqrtf(static_cast<float>(kHeadDim));
    #pragma unroll
    for (int i = 0; i < kVecSize; ++i) {
        data[i] *= kHadamardScale;
    }

    // Part 4: FP8 quantization with per-head scaling
    float local_max = fabsf(data[0]);
    #pragma unroll
    for (int i = 1; i < kVecSize; ++i) {
        local_max = fmaxf(local_max, fabsf(data[i]));
    }

    const float abs_max = warp_reduce_max(local_max);
    const float scale = fmaxf(1e-4f, abs_max) / kFP8E4M3Max;
    const float inv_scale = 1.0f / scale;

    // Pack and store FP8 output
    __nv_fp8x2_e4m3 result0 = pack_fp8(data[0] * inv_scale, data[1] * inv_scale);
    __nv_fp8x2_e4m3 result1 = pack_fp8(data[2] * inv_scale, data[3] * inv_scale);

    // Store as 4 bytes (2 fp8x2) per lane
    uint8_t* out_row = reinterpret_cast<uint8_t*>(q_fp8 + work_id * kHeadDim);
    reinterpret_cast<__nv_fp8x2_e4m3*>(out_row)[lane_id * 2] = result0;
    reinterpret_cast<__nv_fp8x2_e4m3*>(out_row)[lane_id * 2 + 1] = result1;

    // Store combined weight: weight * weight_scale * q_scale
    weights_out[work_id] = weight_val * weight_scale * scale;
}

// Launcher functions
void launch_indexer_bf16(
    const __nv_bfloat16* q_input,
    __nv_fp8_e4m3* q_fp8,
    const __nv_bfloat16* weight,
    float* weights_out,
    float weight_scale,
    const float* freqs_cis,
    const int32_t* positions,
    uint32_t batch_size,
    uint32_t num_heads,
    cudaStream_t stream
) {
    const uint32_t total_works = batch_size * num_heads;
    const uint32_t num_blocks = (total_works + kNumWarps - 1) / kNumWarps;

    fused_indexer_kernel<__nv_bfloat16><<<num_blocks, kBlockSize, 0, stream>>>(
        q_input, q_fp8, weight, weights_out, weight_scale,
        freqs_cis, positions, batch_size, num_heads
    );
}

void launch_indexer_fp16(
    const __half* q_input,
    __nv_fp8_e4m3* q_fp8,
    const __half* weight,
    float* weights_out,
    float weight_scale,
    const float* freqs_cis,
    const int32_t* positions,
    uint32_t batch_size,
    uint32_t num_heads,
    cudaStream_t stream
) {
    const uint32_t total_works = batch_size * num_heads;
    const uint32_t num_blocks = (total_works + kNumWarps - 1) / kNumWarps;

    fused_indexer_kernel<__half><<<num_blocks, kBlockSize, 0, stream>>>(
        q_input, q_fp8, weight, weights_out, weight_scale,
        freqs_cis, positions, batch_size, num_heads
    );
}

// DSV4 Indexer CUDA kernel: RoPE (tail 64) + 128-pt Hadamard + FP8 E4M3 quantization
// Matches SGLang lane-major ordering for bit-exact parity.

#include <cuda_bf16.h>
#include <cuda_fp16.h>
#include <cuda_fp8.h>
#include <cuda_runtime.h>
#include <cstdint>

// Constants
static constexpr int kWarpThreads = 32;
static constexpr int kHeadDim = 128;
static constexpr int kRopeDim = 64;
static constexpr int kVecSize = 4;  // Each thread handles 4 elements
static constexpr float kFP8E4M3Max = 448.0f;
static constexpr int kBlockSize = 128;  // 4 warps per block
static constexpr int kNumWarps = kBlockSize / kWarpThreads;

// Helper: convert bf16 to float
__device__ __forceinline__ float bf16_to_float(__nv_bfloat16 x) {
    return __bfloat162float(x);
}

// Helper: convert fp16 to float
__device__ __forceinline__ float fp16_to_float(__half x) {
    return __half2float(x);
}

// Helper: clamp value to FP8 range
__device__ __forceinline__ float fp8_e4m3_clip(float val) {
    return fmaxf(fminf(val, kFP8E4M3Max), -kFP8E4M3Max);
}

// Helper: pack two fp32 values into fp8x2
__device__ __forceinline__ __nv_fp8x2_e4m3 pack_fp8(float x, float y) {
    return __nv_fp8x2_e4m3(float2{fp8_e4m3_clip(x), fp8_e4m3_clip(y)});
}

// Warp-level max reduction
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = kWarpThreads / 2; offset > 0; offset /= 2) {
        val = fmaxf(val, __shfl_xor_sync(0xFFFFFFFF, val, offset));
    }
    return val;
}

// Aligned vector load/store helpers
template<typename T, int N>
struct alignas(sizeof(T) * N) AlignedVec {
    T data[N];
    __device__ __forceinline__ T& operator[](int i) { return data[i]; }
    __device__ __forceinline__ const T& operator[](int i) const { return data[i]; }

    __device__ __forceinline__ void load(const T* ptr, int idx) {
        *this = reinterpret_cast<const AlignedVec*>(ptr)[idx];
    }

    __device__ __forceinline__ void store(T* ptr, int idx) const {
        reinterpret_cast<AlignedVec*>(ptr)[idx] = *this;
    }
};

// Main kernel template
template<typename DType>
__global__ __launch_bounds__(kBlockSize, 16)
void fused_indexer_kernel(
    const DType* __restrict__ q_input,      // [B, H, 128]
    __nv_fp8_e4m3* __restrict__ q_fp8,      // [B, H, 128]
    const DType* __restrict__ weight,       // [B, H]
    float* __restrict__ weights_out,        // [B, H, 1]
    float weight_scale,
    const float* __restrict__ freqs_cis,    // [max_pos, 64] real/imag interleaved
    const int32_t* __restrict__ positions,  // [B]
    uint32_t batch_size,
    uint32_t num_heads
) {
    const uint32_t warp_id = threadIdx.x / kWarpThreads;
    const uint32_t lane_id = threadIdx.x % kWarpThreads;
    const uint32_t work_id = blockIdx.x * kNumWarps + warp_id;

    const uint32_t total_works = batch_size * num_heads;
    if (work_id >= total_works) return;

    const uint32_t batch_id = work_id / num_heads;
    const DType* input_ptr = q_input + work_id * kHeadDim;
    const int32_t position = positions[batch_id];
    const float* freq_ptr = freqs_cis + position * kRopeDim;

    // Last 16 lanes (lane_id >= 16) own the RoPE tail (64 elements / 4 per lane = 16 lanes)
    const bool is_rope_lane = lane_id >= (kWarpThreads - kRopeDim / kVecSize);

    // Load weight for this (batch, head)
    float weight_val;
    if constexpr (std::is_same_v<DType, __nv_bfloat16>) {
        weight_val = bf16_to_float(weight[work_id]);
    } else {
        weight_val = fp16_to_float(weight[work_id]);
    }

    // Part 1: Load data (each lane owns 4 elements)
    float data[kVecSize];
    float freq[kVecSize];

    AlignedVec<DType, kVecSize> input_vec;
    input_vec.load(input_ptr, lane_id);

    if (is_rope_lane) {
        AlignedVec<float, kVecSize> freq_vec;
        freq_vec.load(freq_ptr, lane_id - (kWarpThreads - kRopeDim / kVecSize));
        #pragma unroll
        for (int i = 0; i < kVecSize; ++i) {
            freq[i] = freq_vec[i];
        }
    }

    #pragma unroll
    for (int i = 0; i < kVecSize; ++i) {
        if constexpr (std::is_same_v<DType, __nv_bfloat16>) {
            data[i] = bf16_to_float(input_vec[i]);
        } else {
            data[i] = fp16_to_float(input_vec[i]);
        }
    }

    // Part 2: RoPE on tail lanes only (4 elems / lane = 2 (real, imag) pairs)
    if (is_rope_lane) {
        // First complex pair
        const float x_real = data[0];
        const float x_imag = data[1];
        const float fxr = freq[0];
        const float fxi = freq[1];

        // Second complex pair  
        const float y_real = data[2];
        const float y_imag = data[3];
        const float fyr = freq[2];
        const float fyi = freq[3];

        // Apply rotation: (x_real + i*x_imag) * (cos + i*sin)
        data[0] = x_real * fxr - x_imag * fxi;
        data[1] = x_real * fxi + x_imag * fxr;
        data[2] = y_real * fyr - y_imag * fyi;
        data[3] = y_real * fyi + y_imag * fyr;
    }

    // Part 3: 128-point Hadamard transform
    // Stage 1: Local 4-point Hadamard (2 butterflies)
    {
        const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
        data[0] = a0 + a1;
        data[1] = a0 - a1;
        data[2] = a2 + a3;
        data[3] = a2 - a3;
    }
    {
        const float a0 = data[0], a1 = data[1], a2 = data[2], a3 = data[3];
        data[0] = a0 + a2;
        data[1] = a1 + a3;
        data[2] = a0 - a2;
        data[3] = a1 - a3;
    }

    // Stage 2: Cross-lane shuffle butterflies (32 lanes = 5 stages)
    #pragma unroll
    for (uint32_t mask = 1; mask < kWarpThreads; mask <<= 1) {
        #pragma unroll
        for (int i = 0; i < kVecSize; ++i) {
            const float other = __shfl_xor_sync(0xFFFFFFFF, data[i], mask, kWarpThreads);
            data[i] = (lane_id & mask) ? (other - data[i]) : (data[i] + other);
        }
    }

    // Apply Hadamard normalization: 1/sqrt(128)
    const float kHadamardScale = rsqrtf(static_cast<float>(kHeadDim));
    #pragma unroll
    for (int i = 0; i < kVecSize; ++i) {
        data[i] *= kHadamardScale;
    }

    // Part 4: FP8 quantization with per-head scaling
    float local_max = fabsf(data[0]);
    #pragma unroll
    for (int i = 1; i < kVecSize; ++i) {
        local_max = fmaxf(local_max, fabsf(data[i]));
    }

    const float abs_max = warp_reduce_max(local_max);
    const float scale = fmaxf(1e-4f, abs_max) / kFP8E4M3Max;
    const float inv_scale = 1.0f / scale;

    // Pack and store FP8 output
    __nv_fp8x2_e4m3 result0 = pack_fp8(data[0] * inv_scale, data[1] * inv_scale);
    __nv_fp8x2_e4m3 result1 = pack_fp8(data[2] * inv_scale, data[3] * inv_scale);

    // Store as 4 bytes (2 fp8x2) per lane
    uint8_t* out_row = reinterpret_cast<uint8_t*>(q_fp8 + work_id * kHeadDim);
    reinterpret_cast<__nv_fp8x2_e4m3*>(out_row)[lane_id * 2] = result0;
    reinterpret_cast<__nv_fp8x2_e4m3*>(out_row)[lane_id * 2 + 1] = result1;

    // Store combined weight: weight * weight_scale * q_scale
    weights_out[work_id] = weight_val * weight_scale * scale;
}

// Launcher functions
void launch_indexer_bf16(
    const __nv_bfloat16* q_input,
    __nv_fp8_e4m3* q_fp8,
    const __nv_bfloat16* weight,
    float* weights_out,
    float weight_scale,
    const float* freqs_cis,
    const int32_t* positions,
    uint32_t batch_size,
