    cudaStream_t stream
) {
    const uint32_t total_works = batch_size * num_heads;
    const uint32_t num_blocks = (total_works + kNumWarps - 1) / kNumWarps;

    fused_indexer_kernel<__nv_bfloat16><<<num_blocks, kBlockSize, 0, stream>>>(
        q_input, q_fp8, weight, weights_out, weight_scale,
        freqs_cis, positions, batch_size, num_heads
