    at::Tensor positions
) {
    // Validate inputs
    TORCH_CHECK(q_input.is_cuda(), "q_input must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(freqs.is_cuda(), "freqs must be a CUDA tensor");
    TORCH_CHECK(positions.is_cuda(), "positions must be a CUDA tensor");

    TORCH_CHECK(q_input.dim() == 3, "q_input must be 3D [B, H, 128]");
    TORCH_CHECK(q_input.size(2) == 128, "q_input last dim must be 128");

    const auto batch_size = q_input.size(0);
    const auto num_heads = q_input.size(1);

    TORCH_CHECK(weight.dim() == 2 && weight.size(0) == batch_size && weight.size(1) == num_heads,
                "weight must be [B, H]");
    TORCH_CHECK(positions.dim() == 1 && positions.size(0) == batch_size,
                "positions must be [B]");

    // Ensure contiguous tensors
    auto q_input_c = q_input.contiguous();
    auto weight_c = weight.contiguous();
    auto freqs_c = freqs.contiguous();
    auto positions_c = positions.to(at::kInt).contiguous();

    // Allocate outputs
    auto q_fp8 = at::empty({batch_size, num_heads, 128}, 
                           q_input.options().dtype(at::kFloat8_e4m3fn));
    auto weights_out = at::empty({batch_size, num_heads, 1},
                                 q_input.options().dtype(at::kFloat));

    // Get CUDA stream
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Launch appropriate kernel based on dtype
    if (q_input.dtype() == at::kBFloat16) {
        launch_indexer_bf16(
            reinterpret_cast<const __nv_bfloat16*>(q_input_c.data_ptr()),
            reinterpret_cast<__nv_fp8_e4m3*>(q_fp8.data_ptr()),
            reinterpret_cast<const __nv_bfloat16*>(weight_c.data_ptr()),
            weights_out.data_ptr<float>(),
            static_cast<float>(weight_scale),
            freqs_c.data_ptr<float>(),
            positions_c.data_ptr<int32_t>(),
            static_cast<uint32_t>(batch_size),
            static_cast<uint32_t>(num_heads),
            stream
        );
    } else if (q_input.dtype() == at::kHalf) {
        launch_indexer_fp16(
            reinterpret_cast<const __half*>(q_input_c.data_ptr()),
            reinterpret_cast<__nv_fp8_e4m3*>(q_fp8.data_ptr()),
            reinterpret_cast<const __half*>(weight_c.data_ptr()),
            weights_out.data_ptr<float>(),
            static_cast<float>(weight_scale),
            freqs_c.data_ptr<float>(),
            positions_c.data_ptr<int32_t>(),
            static_cast<uint32_t>(batch_size),
            static_cast<uint32_t>(num_heads),
            stream
        );
    } else {
        TORCH_CHECK(false, "q_input must be bfloat16 or float16");
    }

    return {q_fp8, weights_out};
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("indexer", &indexer, "DSV4 indexer RoPE+Hadamard+FP8 quant (CUDA)");
}

